                    ['question' => 'Why is a stable core vocabulary layout recommended across contexts?', 'options' => [['text' => 'It looks more organized to caregivers', 'correct' => false], ['text' => 'It supports automatic motor planning by keeping word locations consistent', 'correct' => true], ['text' => 'It reduces the total number of words available', 'correct' => false], ['text' => 'It is required by most device manufacturers', 'correct' => false]], 'explanation' => 'Consistent placement lets motor sequences become automatic, similar to touch-typing, improving speed and reducing cognitive load during navigation.'],
                    ['question' => 'What proportion of everyday spoken language does core vocabulary typically account for?', 'options' => [['text' => 'Around 10%', 'correct' => false], ['text' => 'Around 80%', 'correct' => true], ['text' => 'Nearly 100%', 'correct' => false], ['text' => 'Less than 25%', 'correct' => false]], 'explanation' => 'Language sampling studies repeatedly find that a small set of high-frequency words makes up roughly 80% of daily communicative output.'],
